#ifndef GREEN_CNN_H
#define GREEN_CNN_H

#include "cnn_weights.h"

#define IMG_BYTES (3 * IMG_SIZE * IMG_SIZE)   // 64x64 RGB, channel-first (CHW), uint8
#define OUT_WORDS (NUM_CLASSES + 1)            // NUM_CLASSES logits + predicted class

typedef unsigned char act_t;                   // uint8 activations

// img : DDR address of a 3x64x64 uint8 image (CHW order)
// out : DDR address of OUT_WORDS int32: out[0..NUM_CLASSES-1] = logits, out[NUM_CLASSES] = class
void green_cnn(const unsigned char *img, int *out);

#endif
